from ._common import esc, header_context, table_rows, base_css, tx_field

def berita_html(kind, transaksi_list, nomor_kontrak="", pi_no="", params=None):
    params = params or {}
    rows = list(transaksi_list or [])
    h = header_context(rows, nomor_kontrak, pi_no)
    items = table_rows(rows)
    title = "BERITA ACARA MULAI PEKERJAAN" if kind == "bamp" else "BERITA ACARA SELESAI PEKERJAAN"
    nomor = params.get("nomor", params.get("bamp_no" if kind == "bamp" else "basp_no", ""))
    tanggal = params.get("tanggal", params.get("bamp_date" if kind == "bamp" else "basp_date", "")) or h["Tanggal Performa Invoice"]
    body = "".join(f"<tr><td class='center'>{x['no']}</td><td>{esc(x['uraian'])}</td><td class='center'>{x['qty']:,.2f}</td><td class='center'>{esc(x['unit'])}</td><td>{esc(x['keterangan'])}</td></tr>" for x in items if "material" not in x['kategori'].lower() and "barang" not in x['kategori'].lower())
    verb = "mulai melaksanakan" if kind == "bamp" else "telah menyelesaikan"
    return f'''<!doctype html><html><head><meta charset="utf-8"><title>{title} - {esc(pi_no)}</title><style>{base_css(False)}</style></head><body><div class="page"><div class="header"><b>PT. BANGGAI SENTRAL SULAWESI</b><br><span class="small">General Contractor and Suppliers</span></div><div class="title">{title}</div><table class="noborder"><tr><td><b>Nomor Dokumen</b><br>{esc(nomor or '-')}</td><td><b>Tanggal</b><br>{esc(tanggal)}</td></tr><tr><td><b>Nomor Kontrak</b><br>{esc(h['Nomor Kontrak'])}</td><td><b>Judul Kontrak</b><br>{esc(h['Judul Kontrak'])}</td></tr><tr><td><b>Nomor PO</b><br>{esc(h['Nomor Purchase Order'])}</td><td><b>Tanggal PO</b><br>{esc(h['Tanggal Purchase Order'])}</td></tr></table><p>Pada hari ini, berdasarkan data <b>Proforma Invoice {esc(pi_no)}</b>, PIHAK KEDUA menyatakan {verb} pekerjaan sesuai kontrak dengan rincian sebagai berikut:</p><table class="noborder"><tr><td><b>PIHAK PERTAMA</b><br>{esc(h['Pihak Pertama'])}<br>{esc(h['Alamat Pihak Pertama'])}<br>{esc(h['Diwakili Oleh'])}<br>{esc(h['Selaku'])}</td><td><b>PIHAK KEDUA</b><br>{esc(h['Pihak Kedua'] or 'PT Banggai Sentral Sulawesi')}<br>{esc(h['Alamat Pihak Kedua'])}<br>{esc(h['Diwakili Oleh (P2)'])}<br>{esc(h['Selaku (P2)'])}</td></tr></table><br><table><thead><tr><th>No.</th><th>Keterangan Pekerjaan</th><th>Jumlah</th><th>Satuan</th><th>Catatan</th></tr></thead><tbody>{body}</tbody></table><p>Demikian berita acara ini dibuat untuk dipergunakan sebagaimana mestinya.</p><div class="signature"><div><b>PIHAK PERTAMA</b><div class="sign-space"></div><u>{esc(h['Diwakili Oleh'] or '-')}</u><br>{esc(h['Selaku'] or '-')}</div><div><b>PIHAK KEDUA</b><div class="sign-space"></div><u>{esc(h['Diwakili Oleh (P2)'] or '-')}</u><br>{esc(h['Selaku (P2)'] or '-')}</div></div></div></body></html>'''
